events=[]
class Meta(type):
 @classmethod
 def __prepare__(m,name,bases):
  events.append("prepare")
  return {"initial":7}
 def __new__(m,name,bases,namespace):
  events.append("new")
  return type.__new__(m,name,bases,namespace)
class Field:
 def __set_name__(self,owner,name): self.name=name
 def __get__(self,obj,owner): return obj.value+owner.initial
namespace={"Meta":Meta,"Field":Field}
exec(compile("class Model(metaclass=Meta):\n __slots__=('value',)\n field=Field()\n def __init__(self,value): self.value=value", "model.py", "exec"),namespace)
Model=namespace["Model"]
print(Model(9).field,len(events),events[0],events[1],Model.__dict__["field"].name)

