module=__import__("model")
class Custom(type(module)):
 @property
 def answer(self): return 11
 def __getattribute__(self,name):
  if name=="value": return 9
  return super().__getattribute__(name)
module.__class__=Custom
namespace=module.__dict__
exec("def read(): return value",namespace)
from model import value,answer
print(value,answer,module.read(),namespace is vars(module))

class Meta(type):
 def __matmul__(cls,other): return other.value+7
class Model(metaclass=Meta): pass
class Right:
 __slots__=("value",)
 def __init__(self,value): self.value=value
 def __rpow__(self,base,modulus=None): return self.value+modulus
namespace={"Model":Model,"right":Right(9),"pow":pow}
print(eval("Model @ right",namespace),eval("pow(2,right,5)",namespace))

class A:
 def value(self): return 7
class B:
 def value(self): return 9
class Meta(type):
 def mro(cls): return [cls,B,A,object]
class Model(A,B,metaclass=Meta): pass
view=Model.__dict__
exec("Model.extra=11",{"Model":Model})
print(Model().value(),Model.__mro__[1] is B,view["extra"],"__new__" in vars(object))

class Box:
 __slots__=("value",)
 def __init__(self,value): self.value=value
namespace={"Box":Box}
try: exec(compile("box=Box(7)\nbox.value=9\nraise ValueError('body')","failure.py","exec"),namespace)
except ValueError: print(namespace["box"].value)
print(eval("box.value",namespace))

events=[]
class Descriptor:
 def __set_name__(self,owner,name):
  events.append(name)
  raise ValueError("notification")
namespace={"Descriptor":Descriptor}
try: exec("class Broken:\n field=Descriptor()",namespace)
except ValueError: print("Broken" in namespace,len(events))
class Good: pass
print(isinstance(Good(),Good))

class Model:
 __slots__=("value",)
 def __init__(self): self.value=7
namespace={"Model":Model}
exec(compile("instance=Model()\ndef fail():\n print(instance.value)\n raise ValueError('original')\nfail()","composed-original.py","exec"),namespace)

class Box: pass
namespace={"Box":Box}
try: exec("box=Box()\nbox.value=7\nprint(box.value)\n__import__('outside')",namespace)
except ImportError: print("denied",namespace["box"].value)
